const body = $input.first().json.body || {};
const kontext = body.context || {};
const postId = String(body.post_id || '');
if (!/^[a-z0-9]{26}$/.test(postId)) {
  throw new Error('Ungueltige post_id');
}
if (!['ticket', 'task'].includes(kontext.aktion) || !/^[a-f0-9]{32}$/.test(String(kontext.nonce || ''))) {
  throw new Error('Unbekannte Aktion');
}
return [{ json: { post_id: postId, aktion: kontext.aktion, nonce: kontext.nonce, user_name: String(body.user_name || 'unbekannt') } }];

const eingabe = $('Eingabe pruefen').first().json;
const post = $('Post laden').first().json;
const ich = $input.first().json;
const props = post.props || {};
if (!ich.id || post.user_id !== ich.id) {
  throw new Error('Post stammt nicht vom Bot');
}
if (!props.aktion_nonce || props.aktion_nonce !== eingabe.nonce) {
  throw new Error('Aktion nicht mehr gueltig');
}
return [{ json: { aktion: eingabe.aktion, prio: props.aktion_prio || 'medium', titel: props.aktion_titel || 'Alert aus Mattermost', text: props.aktion_text || '', message: post.message, user: eingabe.user_name } }];

const daten = $('Nonce pruefen').first().json;
const ticket = $input.first().json;
const url = 'https://support-tech.pkr-lab.de/#ticket/zoom/' + ticket.id;
return [{
  json: {
    update: {
      message: daten.message,
      props: {
        aktion_nonce: '',
        attachments: [{ fallback: 'Ticket angelegt', color: '#2e7d32', text: '\u{1F3AB} Ticket #' + ticket.number + ' von @' + daten.user + ' angelegt: ' + url }],
      },
    },
    ephemeral_text: 'Ticket #' + ticket.number + ' angelegt.',
  },
}];

const daten = $('Nonce pruefen').first().json;
const nutzer = $input.first().json || {};
const BOARD_ID = 'by66ipbhnj3nx3ew3p31tuqhhha';
const PROP = { status: 'a972dc7a-5f4c-45d2-8044-8c28c69717f1', priority: 'd3d682bf-e074-49d9-8df5-7320921c2d23', label: 'ame474iofuqcm5pjwscajr7dxsw', repo: 'ady97jwwt4p1u3sxpqjjpf89gco', assignee: 'axkhqa4jxr3jcqe4k87g8bhmary' };
const PRIORITAET = { high: 'd3bfb50f-f569-4bad-8a3a-dd15c3f60101', medium: '87f59784-b859-4c24-8ebe-17c766e081dd', low: '98a57627-0f76-471d-850d-91f3ed9fd213' };
const properties = {
  [PROP.status]: 'ayz81h9f3dwp7rzzbdebesc7ute',
  [PROP.priority]: PRIORITAET[daten.prio] || PRIORITAET.medium,
  [PROP.label]: 'az978coch7kffx5ctuk9k86yx4y',
  [PROP.repo]: ['a3x185h633tahzo6t46pgr6ox7e'],
};
if (nutzer.id) properties[PROP.assignee] = nutzer.id;
const jetzt = Date.now();
const kartenId = 'block-0';
const textId = 'block-1';
const metaId = 'block-2';
const block = (id, parentId, typ, titel, felder) => ({ id, boardId: BOARD_ID, parentId, schema: 1, type: typ, title: titel, createAt: jetzt, updateAt: jetzt, deleteAt: 0, fields: felder });
const blocks = [
  block(kartenId, BOARD_ID, 'card', daten.titel, { icon: '\u{1F6A8}', isTemplate: false, contentOrder: [textId, metaId], properties }),
  block(textId, kartenId, 'text', daten.text || daten.titel, {}),
  block(metaId, kartenId, 'text', 'Automatisch aus einer Alertmanager-Meldung in Mattermost angelegt von @' + daten.user + '.', {}),
];
return [{ json: { blocks, titel: daten.titel } }];

